package br.com.erp.fiscal;

import br.com.erp.auth.*;
import br.com.erp.shared.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.util.*;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;

@Service
public class FiscalConfiguration {
 private final JdbcTemplate db;private final BranchAccess access;private final WorkflowSupport flow;private final Audit audit;private final FiscalSecrets secrets;private final ObjectMapper json;
 public FiscalConfiguration(JdbcTemplate db,BranchAccess access,WorkflowSupport flow,Audit audit,FiscalSecrets secrets,ObjectMapper json){this.db=db;this.access=access;this.flow=flow;this.audit=audit;this.secrets=secrets;this.json=json;}
 public record Issuer(@NotBlank @Pattern(regexp="[A-Z0-9]{12}[0-9]{2}") String cnpj,@NotBlank @Size(max=60) String legalName,@NotBlank @Pattern(regexp="[0-9]{8,14}") String stateRegistration,@NotBlank @Pattern(regexp="[1-4]") String taxRegime,@NotBlank @Pattern(regexp="GO") String state,@NotBlank @Pattern(regexp="52[0-9]{5}") String municipalityCode,@NotBlank @Size(max=60) String municipality,@NotBlank @Size(max=60) String street,@NotBlank @Size(max=60) String number,@NotBlank @Size(max=60) String district,@NotBlank @Pattern(regexp="[0-9]{8}") String postalCode,@NotNull @Min(1) @Max(999) Integer nfeSeries,@NotNull @Min(1) @Max(999) Integer nfceSeries){}
 public record Save(@NotNull UUID requestId,@NotNull UUID branchId,@NotNull FiscalContext.Environment environment,@NotNull @Min(0) Long version,@NotNull @Valid Issuer issuer){}
 public record Credential(@NotNull UUID requestId,@NotNull UUID branchId,@NotNull FiscalContext.Environment environment,@NotNull @Min(1) Long version,@NotBlank @Size(max=270000) String certificateBase64,@NotNull @Size(max=512) String password){}
 private record Bundle(String pfx,String password){}
 private String encode(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException("Não foi possível serializar configuração fiscal.");}}
 private <T>T decode(String value,Class<T> type){try{return json.readValue(value,type);}catch(Exception e){throw new IllegalStateException("Configuração fiscal persistida inválida.");}}
 @Transactional(readOnly=true) public Map<String,Object> get(Actor a,UUID branch,FiscalContext.Environment environment){access.requireBranch(a,branch);var rows=db.queryForList("SELECT issuer_json,version,credential_ciphertext,certificate_subject,certificate_expires_at FROM fiscal_establishment WHERE tenant_id=? AND branch_id=? AND environment=?",a.tenantId(),branch,environment.name());var out=new LinkedHashMap<String,Object>();out.put("branchId",branch);out.put("environment",environment);out.put("provider","DIRECT_SEFAZ");out.put("keyConfigured",secrets.configured());out.put("configured",!rows.isEmpty());out.put("version",rows.isEmpty()?0:rows.getFirst().get("version"));if(!rows.isEmpty()){var row=rows.getFirst();out.put("issuer",decode((String)row.get("issuer_json"),Issuer.class));out.put("certificateConfigured",row.get("credential_ciphertext")!=null);out.put("certificateSubject",row.get("certificate_subject"));out.put("certificateExpiresAt",row.get("certificate_expires_at"));}return out;}
 @Transactional public Map<String,Object> save(Actor a,Save input){flow.lock(a);access.requireBranch(a,input.branchId());String payload=encode(input.issuer()),hash=flow.hash(input.branchId(),input.environment(),input.version(),payload);UUID old=flow.replay(a,input.requestId(),"FISCAL_CONFIGURATION",hash);if(old!=null)return get(a,input.branchId(),input.environment());var rows=db.query("SELECT version,issuer_json FROM fiscal_establishment WHERE tenant_id=? AND branch_id=? AND environment=?",(r,i)->Map.entry(r.getLong(1),r.getString(2)),a.tenantId(),input.branchId(),input.environment().name());if((rows.isEmpty()?0:rows.getFirst().getKey())!=input.version().longValue())throw flow.conflict("Configuração alterada. Atualize.");if(!rows.isEmpty()&&!decode(rows.getFirst().getValue(),Issuer.class).cnpj().equals(input.issuer().cnpj()))throw flow.conflict("CNPJ da configuração não pode mudar. Utilize o estabelecimento correto.");if(rows.isEmpty())db.update("INSERT INTO fiscal_establishment(tenant_id,branch_id,environment,provider,issuer_json,created_by) VALUES(?,?,?,'DIRECT_SEFAZ',?,?)",a.tenantId(),input.branchId(),input.environment().name(),payload,a.userId());else db.update("UPDATE fiscal_establishment SET issuer_json=?,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE tenant_id=? AND branch_id=? AND environment=?",payload,a.tenantId(),input.branchId(),input.environment().name());flow.record(a,input.requestId(),"FISCAL_CONFIGURATION",hash,input.branchId());audit.record(a,"FISCAL_CONFIGURATION_CHANGED",input.branchId());return get(a,input.branchId(),input.environment());}
 @Transactional public Map<String,Object> certificate(Actor a,Credential input){flow.lock(a);access.requireBranch(a,input.branchId());var context=new FiscalContext(a.tenantId(),input.branchId(),input.environment());String hash=flow.hash(input.branchId(),input.environment(),input.version(),input.certificateBase64(),input.password());if(flow.replay(a,input.requestId(),"FISCAL_CERTIFICATE",hash)!=null)return get(a,input.branchId(),input.environment());var current=get(a,input.branchId(),input.environment());if(!Boolean.TRUE.equals(current.get("configured"))||((Number)current.get("version")).longValue()!=input.version())throw flow.conflict("Salve a configuração atual antes de cadastrar A1.");byte[] bytes;try{bytes=Base64.getDecoder().decode(input.certificateBase64());}catch(IllegalArgumentException e){throw flow.bad("Arquivo A1 inválido.");}char[] password=input.password().toCharArray();try{var cert=new FiscalCertificate(bytes,password);String encrypted=secrets.encrypt(context,encode(new Bundle(input.certificateBase64(),input.password())));db.update("UPDATE fiscal_establishment SET credential_ciphertext=?,certificate_subject=?,certificate_expires_at=?,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE tenant_id=? AND branch_id=? AND environment=?",encrypted,cert.certificate().getSubjectX500Principal().getName(),cert.certificate().getNotAfter().toInstant().atOffset(java.time.ZoneOffset.UTC),a.tenantId(),input.branchId(),input.environment().name());}catch(IllegalArgumentException e){throw flow.bad(e.getMessage());}finally{Arrays.fill(password,'\0');Arrays.fill(bytes,(byte)0);}flow.record(a,input.requestId(),"FISCAL_CERTIFICATE",hash,input.branchId());audit.record(a,"FISCAL_CERTIFICATE_CHANGED",input.branchId());return get(a,input.branchId(),input.environment());}
 public SefazTransport transport(Actor a,UUID branch,FiscalContext.Environment environment){access.requireBranch(a,branch);var values=db.query("SELECT credential_ciphertext FROM fiscal_establishment WHERE tenant_id=? AND branch_id=? AND environment=?",(r,i)->r.getString(1),a.tenantId(),branch,environment.name());if(values.isEmpty()||values.getFirst()==null)throw flow.conflict("Configure o certificado A1 da filial neste ambiente.");var bundle=decode(secrets.decrypt(new FiscalContext(a.tenantId(),branch,environment),values.getFirst()),Bundle.class);char[] password=bundle.password().toCharArray();byte[] pfx=Base64.getDecoder().decode(bundle.pfx());try{return new FiscalCertificate(pfx,password).transport(password);}finally{Arrays.fill(password,'\0');Arrays.fill(pfx,(byte)0);}}
}
